"""Post-process and plot Density of States data generated by SuperConga.

Parse the Density of States (DOS) data-files generated by the SuperConga runner
(superconga.py), and draw 2D and 1D plots.  For more informtation and verbose
comments about the plotting library, see e.g. plotter.py and the online
documentation.
"""

# Built-in modules and third-party libraries.
import matplotlib.pyplot as plt
import numpy as np
import os
import sys

# Custom libraries.
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "tools/"))
from python_libraries.file_io import parse_json_files
from python_libraries.file_io import parse_convergence
from python_libraries.file_io import parse_grid_quantity
from python_libraries.parameter_setup import argument_parsing as AP
from python_libraries.parameter_setup import argument_validation as AV
from python_libraries.plotting import field_plotting

# Global settings.


# Main.
def main() -> None:
    # ========================================================================#
    #                            ARGUMENT PARSING                             #
    # ========================================================================#
    # Use settings for a plotter frontend (frontend can be runner or plotter).
    frontend = "ldos_plotter"
    # Program name and description for command-line help message.
    program_name = "SuperConga DOS plotter"
    program_description = "Interactive plotting of Density of States (DOS) data. The DOS is plotted as a 2D heatmap and as averaged 1D curves. Specify DOS data path with arguments: -p | --data-path. Note that postprocess.py can be used to compute the DOS from converged simulations."
    # Parse command-line arguments, and possibly a JSON file which specifies
    # config plotting parameters. The JSON file is provided via: -f|--file.
    plot_config_parameters, _ = AP.parse_command_line_arguments(
        program_name=program_name,
        program_description=program_description,
        frontend=frontend,
    )

    # ========================================================================#
    #                           ARGUMENT VALIDATION                           #
    # ========================================================================#
    # Validate user input (e.g. check that data path exists).
    # Exit if there are errors.
    success = AV.validate_arguments(
        arguments_dict=plot_config_parameters, frontend=frontend
    )
    if not success:
        status_code = 1
        sys.exit(status_code)

    # ========================================================================#
    #                            PARSE DATA FILES                             #
    # ========================================================================#
    # Parse simulation parameters from json, get result as dictionary.
    simulation_parameters = parse_json_files.parse_config(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Get geometry mask.
    geometry = parse_grid_quantity.parse_geometry_numpy(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse "internal parameters" from json, get result as dictionary.
    internal_parameters = parse_json_files.parse_internal_parameters(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse "post-processing" parameters (LDOS info) from json, get result as
    # dictionary.
    post_processing_parameters = parse_json_files.parse_post_processing(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse DOS data as a dictionary: dos_data["energy"], dos_data["dos"] gives
    # the energy and DOS respectively.
    dos_data = parse_convergence.parse_dos(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse LDOS data as a dictionary with numpy 2D and 3D arrays. The LDOS
    # data is accessible as: ldos_data["ldos"][energy_idx,y_idx,x_idx], where
    # y_idx and x_idx are the discrete indices for data at x- and y-coordinates
    # given by
    # y = (y_idx / simulation_parameters['points_per_coherence_length']),
    # and energy is given by
    # energy = np.linspace(energy_min, energy_max, num_energies)[energy_idx],
    # with energy_min = post_processing_data["energy_min"] etc.
    # To get LDOS at specific coordinate, use e.g.
    # LDOS = ldos_data[:,y_idx,x_idx].
    ldos_data = parse_grid_quantity.parse_ldos(
        base_path=plot_config_parameters["general"]["data_path"],
        internal_parameters=internal_parameters,
    )

    # Mask region outside grain with a false color, to more easily
    # distinguish grain boundaries.
    (num_energies, num_y, num_x) = np.shape(ldos_data["ldos"])
    for energy_idx in range(0, num_energies):
        ldos_data["ldos"][energy_idx, geometry["mask"] == 0] = np.nan

    # ========================================================================#
    #                                PLOT DATA                                #
    # ========================================================================#
    # Plot DOS and LDOS with matplotlib. Get reference to energy slider and
    # point-contact (STM tip) slider, to prevent garbage collector from
    # breaking plot interactivity.
    energy_slider, point_contact_slider = field_plotting.plot_ldos(
        ldos_data=ldos_data,
        dos_data=dos_data,
        plot_parameters=plot_config_parameters,
        simulation_parameters=simulation_parameters,
        post_processing_parameters=post_processing_parameters,
    )

    # Show plot windows.
    plt.show()

    # Exit Python program.
    status_code = 0
    sys.exit(status_code)


if __name__ == "__main__":
    main()
